}

// Complete C Function Handling All 3 Insertion Cases
struct Node* insertNode(struct Node* head, int val, int position) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = val;
    newNode->next = NULL;

    // CASE 1: Insert at Beginning (position == 1 or empty list)
    if (position == 1 || head == NULL) {
        newNode->next = head;
        head = newNode;
        return head;
    }

    // Traverse to (position - 1)
    struct Node* temp = head;
    for (int i = 1; i < position - 1 && temp->next != NULL; i++) {
        temp = temp->next;
    }

    // CASE 2 & 3: Insert at End or Intermediate Position
    newNode->next = temp->next;
    temp->next = newNode;

    return head;
}

// C Function to Delete Intermediate Node by Value
struct Node* deleteIntermediateNode(struct Node* head, int key) {
    if (head == NULL) {
        printf("Error: List is empty (Underflow)!\n");
        return NULL;
    }

    struct Node* curr = head;
    struct Node* prev = NULL;

    // If head node itself holds the key to be deleted
    if (curr != NULL && curr->data == key) {
        head = curr->next; // Change head
        free(curr);        // Free old head
        return head;
    }

    // Search for key, keeping track of previous node
    while (curr != NULL && curr->data != key) {
        prev = curr;
        curr = curr->next;
    }

    // If key was not present in the linked list
    if (curr == NULL) {
        printf("Node with value %d not found!\n", key);
        return head;
    }

    // Unlink the node from linked list and free memory
    prev->next = curr->next;
    free(curr);

    return head;
}

