int evaluatePostfix(char* exp) {
    int stack[100], top = -1;

    for (int i = 0; exp[i] != '\0'; i++) {
        if (isdigit(exp[i])) {
            stack[++top] = exp[i] - '0'; // Push operand
        } else if (exp[i] != ' ') {
            int val2 = stack[top--];
            int val1 = stack[top--];
            switch (exp[i]) {
                case '+': stack[++top] = val1 + val2; break;
                case '-': stack[++top] = val1 - val2; break;
                case '*': stack[++top] = val1 * val2; break;
                case '/': stack[++top] = val1 / val2; break;
                case '^': stack[++top] = pow(val1, val2); break;
            }
        }
    }
    return stack[top]; // Final computed answer
}

