// Recursive Backtracking: N-Queens Core
int isSafe(int board[N][N], int row, int col) {
    // Check column and diagonals for attacks
    for (int i = 0; i < row; i++)
        if (board[i][col]) return 0;
    for (int i = row, j = col; i >= 0 && j >= 0; i--, j--)
        if (board[i][j]) return 0;
    for (int i = row, j = col; i >= 0 && j < N; i--, j++)
        if (board[i][j]) return 0;
    return 1;
}

int solveNQueens(int board[N][N], int row) {
    if (row >= N) return 1; // All queens placed!

    for (int col = 0; col < N; col++) {
        if (isSafe(board, row, col)) {
            board[row][col] = 1; // TRIAL STEP
            if (solveNQueens(board, row + 1)) return 1;
            board[row][col] = 0; // BACKTRACK STEP (Undo choice)
        }
    }
    return 0; // Trigger backtrack to previous row
}

