// BFS Implementation in C using FIFO Queue
void BFS(int start, int V) {
    int visited[MAX] = {0};
    int queue[MAX], front = 0, rear = 0;

    // Enqueue start vertex and mark visited
    visited[start] = 1;
    queue[rear++] = start;

    while (front < rear) {
        int u = queue[front++]; // Dequeue
        printf("%d ", u);

        // Inspect all adjacent vertices
        for (int v = 0; v < V; v++) {
            if (adj[u][v] == 1 && !visited[v]) {
                visited[v] = 1;
                queue[rear++] = v; // Enqueue neighbor
            }
        }
    }
}

// Floyd-Warshall All-Pairs Shortest Path: O(V^3)
#define INF 99999
#define V 4

void floydWarshall(int graph[V][V]) {
    int dist[V][V];

    // Initialize dist matrix with input graph weights
    for (int i = 0; i < V; i++)
        for (int j = 0; j < V; j++)
            dist[i][j] = graph[i][j];

    // Outer loop selects intermediate vertex k
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }
}

// Kahn's In-degree Algorithm for Topological Sort
void topologicalSortKahn(int V) {
    int inDegree[MAX] = {0};
    int queue[MAX], front = 0, rear = 0;
    int count = 0;

    // 1. Calculate in-degrees
    for (int u = 0; u < V; u++)
        for (int v = 0; v < V; v++)
            if (adj[u][v] == 1) inDegree[v]++;

    // 2. Enqueue 0-indegree vertices
    for (int i = 0; i < V; i++)
        if (inDegree[i] == 0) queue[rear++] = i;

    // 3. Process queue
    while (front < rear) {
        int u = queue[front++];
        printf("%d ", u);
        count++;

        for (int v = 0; v < V; v++) {
            if (adj[u][v] == 1) {
                if (--inDegree[v] == 0)
                    queue[rear++] = v;
            }
        }
    }
    if (count != V) printf("Error: Graph contains a cycle!\n");
}

