// Complete C Implementation: Two Stacks in One Array
#define N 100
int arr[N];
int top1 = -1;
int top2 = N;

// Push into Stack 1
void push1(int val) {
    if (top1 + 1 == top2) {
        printf("Stack Overflow! Array is completely full.\n");
        return;
    }
    arr[++top1] = val;
}

// Push into Stack 2
void push2(int val) {
    if (top1 + 1 == top2) {
        printf("Stack Overflow! Array is completely full.\n");
        return;
    }
    arr[--top2] = val;
}

// Pop from Stack 1
int pop1() {
    if (top1 == -1) {
        printf("Stack 1 Underflow!\n");
        return -1;
    }
    return arr[top1--];
}

// Pop from Stack 2
int pop2() {
    if (top2 == N) {
        printf("Stack 2 Underflow!\n");
        return -1;
    }
    return arr[top2++];
}
